menu.event:
local numItems = game.numBakeryItems()
if(numItems > 0) then local itemHeight = element:GetElement("BakeryItems"):GetElement("bakeryItem0"):absH()
if((numItems*itemHeight) <= element:GetElement("BakeryItems"):absH()) then element["ScrollBar"]["Sprite"]("visible"):SetInt(0) element["ScrollMarker"]["Marker"]("visible"):SetInt(0) end end
